/**
 * Free downloadable templates (files in public/templates/, generated by
 * scripts/make-templates.py). Each one has its own SEO page at
 * /templates/<slug>, listed on /templates. The guidance text is what earns
 * the ranking; the download is what earns the visit.
 */
export interface TemplateDoc {
  slug: string
  /** Short name used in cards and breadcrumbs. */
  name: string
  seoTitle: string
  seoDescription: string
  h1: string
  file: string
  format: 'Excel' | 'Word'
  intro: string
  includes: string[]
  /** What the downloaded file looks like, drawn on the page. */
  preview: { kind: 'sheet'; columns: string[]; rows: string[][] } | { kind: 'doc'; lines: string[] }
  steps: string[]
  guide: { heading: string; body: string[] }[]
  faqs: { q: string; a: string }[]
  /** The part of The Counsel that replaces this template. */
  product: { pitch: string; to: string; label: string }
}

